package main

/*
#include <string.h>
*/
import "C"
import "unsafe"

func sumLens(items []string) (total int) {
	// BAD: one cgo crossing per element — the handoff dominates.
	for _, s := range items {
		cs := C.CString(s)
		total += int(C.strlen(cs))
		C.free(unsafe.Pointer(cs))
	}
	return // prefer passing one big buffer in a single C call instead
}

