/*
#include <stdlib.h>
*/
import "C"

func CRandSeed(seed uint32) int {
	C.srand(C.uint(seed)) // seed C's PRNG (global state in C)
	r := C.rand()         // one pseudo-random value
	return int(r)         // convert C.int back to Go int
}

/*
#include <stdlib.h>
#include <string.h>

// dup returns a NEW malloc'd copy of n bytes (caller must free).
static void* dup(const void* src, size_t n) {
    void* out = malloc(n);
    if (out != NULL && n > 0) memcpy(out, src, n);
    return out;
}
*/
import "C"
import "unsafe"

func CopyBytes(data []byte) []byte {
	n := C.size_t(len(data))
	// CBytes makes a C-heap copy so C never retains the Go backing array.
	src := C.CBytes(data)
	defer C.free(src) // free the input copy

	dst := C.dup(src, n) // C mallocs its own buffer
	defer C.free(dst)    // free the output copy too

	// GoBytes copies the C buffer into GC-managed Go memory.
	return C.GoBytes(dst, C.int(n))
}
